"use strict";(globalThis.webpackChunkp_vs_np_docs=globalThis.webpackChunkp_vs_np_docs||[]).push([[5594],{12499(e){e.exports=JSON.parse('{"tag":{"label":"conp","permalink":"/azeon/p-vs-np/tags/conp","allTagsPath":"/azeon/p-vs-np/tags","count":3,"items":[{"id":"np-completeness/np-completeness-in-minesweeper","title":"NP-Completeness in Minesweeper","description":"Phase 2 ends with a game. Checking whether the numbers on a Minesweeper board even make sense is NP-Complete, you can build logic gates out of mines, and knowing whether a square is safe turns out to be hard in a different way.","permalink":"/azeon/p-vs-np/np-completeness/np-completeness-in-minesweeper"},{"id":"complexity-zoo/tautologies-and-conp-completeness","title":"Tautologies and coNP-Completeness","description":"A tautology is a formula that\'s true no matter what. Deciding whether a formula is one is the hardest problem in coNP, and it\'s tied to an old question: does every true statement have a short proof?","permalink":"/azeon/p-vs-np/complexity-zoo/tautologies-and-conp-completeness"},{"id":"complexity-zoo/the-class-conp","title":"The Class coNP","description":"NP is about problems where a yes has a short proof. Flip it, and you get coNP, where a no has a short proof. It sounds like a small twist. It turns out to be its own unsolved problem, sitting right next to P vs NP.","permalink":"/azeon/p-vs-np/complexity-zoo/the-class-conp"}],"unlisted":false}}')}}]);